meta={}
for name,s in shapes.items():
 im=Image.open(source/(s['id']+'.jpg')).convert('RGB');scale=im.width/1200
 pts=[((s['origin'][0]+x/2)*scale,(s['origin'][1]+y/2)*scale) for x,y in s['points']]
 mask=Image.new('L',im.size);ImageDraw.Draw(mask).polygon(pts,fill=255)
 # Sub-pixel antialiasing softens only the matte, never the photo RGB.
 rgb=np.asarray(im).astype(float);rr,gg,bb=rgb[:,:,0],rgb[:,:,1],rgb[:,:,2]
 raw=np.asarray(mask)>0
 green=(gg>rr*1.22)&(gg>bb*1.25)&(gg-rr>14)&(gg>45)
 sky=(bb>rr*1.05)&(gg>rr*1.05)&(bb>gg*1.02)&(gg>95)
 boundary=distance_transform_edt(raw)<(8*scale)
 if name in ('collin','steppa'):
  green=(gg>rr*1.04)&(gg>bb*1.1)&(gg-rr>3)&(gg>40)
 if name=='collin':
  protect=Image.new('L',im.size)
  pp=[(430,270),(510,235),(640,165),(734,164),(785,245),(778,320),(706,370),(619,385),(503,370),(440,344)]
  pp=[((s['origin'][0]+x/2)*scale,(s['origin'][1]+y/2)*scale) for x,y in pp]
  ImageDraw.Draw(protect).polygon(pp,fill=255)
  green=green&~(np.asarray(protect)>0)
 candidate=green
 external=binary_propagation(~raw,mask=(~raw)|candidate)
 refined=minimum_filter(raw&~external,size=5)
 mask=Image.fromarray((refined*255).astype('uint8')).filter(ImageFilter.GaussianBlur(.6))
 bbox=mask.getbbox();pad=3;bbox=(max(0,bbox[0]-pad),max(0,bbox[1]-pad),min(im.width,bbox[2]+pad),min(im.height,bbox[3]+pad))
 rgba=im.convert('RGBA');rgba.putalpha(mask);rgba=rgba.crop(bbox)
 filename=name+'-original-cutout-v1';rgba.save(out/(filename+'.webp'),lossless=True,exact=True,method=6)
 decoded=Image.open(out/(filename+'.webp')).convert('RGBA');a=np.asarray(decoded);original=np.asarray(im.crop(bbox));inside=a[:,:,3]==255
 assert np.array_equal(a[:,:,:3][inside],original[inside]),name+' photo pixels changed'
 assert all(decoded.getpixel(p)[3]==0 for p in [(0,0),(0,decoded.height-1),(decoded.width-1,0),(decoded.width-1,decoded.height-1)])
 for w in ((480,800,1280) if name=='collin' else (480,800)):
  if w<rgba.width:rgba.resize((w,round(rgba.height*w/rgba.width)),Image.Resampling.LANCZOS).save(out/(filename+f'-{w}.webp'),lossless=True,exact=True,method=6)
 meta[name]={'original':s['id']+'.jpg','file':filename+'.webp','size':rgba.size,'source_crop':bbox,'foreground_RGB_equals_source_at_opaque_pixels':True}
 # QA checker background only.
 qa=Image.new('RGB',rgba.size,'#414747');qa.paste(rgba,mask=rgba.getchannel('A'));qa.thumbnail((1000,900));qa.save('/workspace/scratch/874565f258f7/review/'+name+'-matte-qa.png')
# Real field textures; no athlete pixels or generative fill.
for name,imgid,box,size in [('collin','DSC01779',(0,1650,3384,2256),(1672,941)),('steppa','DSC03145',(2500,100,4305,2870),(1000,1250))]:
 im=Image.open(source/(imgid+'.jpg')).convert('RGB').crop(box).resize(size,Image.Resampling.LANCZOS)
 im=ImageOps.grayscale(im);raw_field=im.copy();arr=uniform_filter1d(np.asarray(im).astype(float),size=65,axis=1,mode='nearest');im=Image.fromarray(np.clip(arr,0,255).astype('uint8'))
 if name=='collin':
  # Preserve the real grass aspect ratio in the foreground; blur only depth behind it.
  texture=ImageOps.grayscale(Image.open(source/(imgid+'.jpg')).convert('RGB').crop((800,1600,2600,2256)))
  texture=texture.resize((size[0],round(texture.height*size[0]/texture.width)),Image.Resampling.LANCZOS)
  ground=im.copy();ground.paste(texture,(0,size[1]-texture.height))
  ramp=np.linspace(0,1,size[1]);ramp=np.clip((ramp-.36)/.26,0,1)
  blend=Image.fromarray(np.repeat((ramp*255).astype('uint8')[:,None],size[0],axis=1))
  im=Image.composite(ground,im,blend)
 im=ImageEnhance.Contrast(im).enhance(1.15);im=ImageEnhance.Brightness(im).enhance(.54)
 im.save(out/(name+'-original-field-v1.webp'),quality=88,method=6)
Path('docs/ORIGINAL-PHOTO-MATTES.json').write_text(json.dumps(meta,indent=2)+'\n')
print(json.dumps(meta,indent=2))
